# coding: utf-8
from pathlib import Path
import json,re
p=Path(__file__).resolve().parent
read=lambda n:json.loads((p/n).read_text())
first,filled,jsc,pressure,churn,live=[read(n) for n in ['native-first-load-results.json','native-filled-first-load-results.json','recovery-jsc-results.json','native-pressure-results.json','mixed-native-churn-results.json','live-translation-results.json']]
tests=(p/'tests.log').read_text();assert '# tests 1990' in tests and '# pass 1990' in tests and '# fail 0' in tests
assert len(first['runs'])==204 and len(filled['runs'])==204 and len(jsc['runs'])==48
assert sum(x['lyricResponses'] for x in churn['results'])==4800
assert all(x['warmHTTP']==0 and x['activeHTTP']==0 and x['maxActiveHTTP']==1 for x in churn['results'])
assert all(x['peakHTTP']==1 and x['peakLiveInvocations']==2 and x['admissionTimers']==0 for x in pressure['comparisons'])
assert all(r['changed']==4 and r['coldHTTP']==1 and r['warmHTTP']==0 and r['done']==1 and r['active']==0 for r in live['results'])
out=['# VerseLyrics 3.1.8 validation and measurements','','Functional translation recovery with bounded retries. Desktop compiled-host mocks and macOS JavaScriptCore are not the Loon/iPhone VPN process. All common-path regressions and the extra cost of newly working translation paths are retained below. Network-free tables exclude service latency.','','## Confirmed repair scope','','- 1,990 automated tests pass, including 98 added cases (60 compiled native client/format cases). Fourteen older expectations were updated for the deliberate per-row retention policy; exact result counts and original alignment remain mandatory.','- In the same readable-core harness, stale Korean/English identity caches yield 0 translations / 0 requests on 3.1.7, and 3 translations / 1 request on 3.1.8; warm reopen uses 0 requests. A correctly sized reply containing one null row changes from 0 translations to 2 valid translations without shifting positions.','- Original-as-translation and individually invalid aligned answers get a 30-second row retry time in the existing bounded translation record. Successful rows stay cached. Retry requires a later lyric request; no background timer, queue, parallel task or higher timeout is introduced.','- Six sources, official static-to-timed replacement switch, native words/timestamps/colors, meaningful mixed English, Chinese conversion guards and vocal-language rules remain.','','## Reported track and evidence boundary','','Spotify public embed metadata confirms Girl\'s Day – Come Slowly, track 6n7jFn3rgC6qWjsYaPJfB8, duration 249213 ms. No protected Spotify lyric response or user cache was captured; the anonymous embed session lyrics probe returned HTTP 400. The reproduced failure states and live translator probes use self-written Korean/English rows. They establish the repaired paths, not the exact cause of the user\'s phone instance or full-song UI acceptance. No account credentials or real song lyrics are published.','','## First-load comparisons','','Each table uses 204 fresh Node processes (six alternating trials per version/scenario), one newly compiled Loon script/VM per process, and 32 MiB old-space. Output hashes and HTTP counts match on these unchanged ordinary cases. Populated runs start with 48000–60000 unrelated cache characters. Samples include harness/compiler/code-cache overhead and do not capture every transient/native allocation.']
for name,d in [('Empty cache',first),('Populated cache',filled)]:
 out+=['','### '+name,'','| Scenario | Baseline ms | Candidate ms | Time change | Sampled heap change |','| --- | ---: | ---: | ---: | ---: |']
 for r in d['comparisons']:
  a,b=r['baseline'],r['candidate'];out.append('| '+r['scenario']+' | %.3f | %.3f | %+.3f%% | %+.3f%% |'%(a['medianMs'],b['medianMs'],(b['medianMs']/a['medianMs']-1)*100,(b['sampledMaxHeapBytes']/a['sampledMaxHeapBytes']-1)*100))
out+=['','## macOS JavaScriptCore','','48 fresh processes, six alternating trials per version/case. Same self-written Korean/English protobuf fixtures and zero-latency native HTTP mocks. Stale-cache and partial-result baseline cases deliberately fail to translate: candidate extra work is reported as extra work, not as a memory reduction. Footprint and RSS include harness, JIT and process overhead.','','| Case | Version | Processing ms | Sampled peak footprint bytes | Max RSS bytes | HTTP | Translated rows |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
for r in jsc['summary']:out.append('| %s | %s | %.3f | %.0f | %.0f | %d | %d |'%(r['case'],r['version'],r['milliseconds'],r['sampledPeakFootprint'],r['maxRSS'],r['calls'],r['translatedRows']))
out+=['','## Repeated responses and limits','','- Twenty native client/format/cache-mode playlists complete 4,800 lyric responses; warm reopen HTTP is 0, sampled active HTTP is at most 1, and no active HTTP remains at completion. Standard/compact bounds are checked on every response.','- Sixteen arrival-pressure processes retain at most 2 live mock invocations, 1 active HTTP and 0 admission timers. Callback work is settled before completion; native synchronous storage remains advisory, not an atomic device-wide semaphore.','- General native feature fixtures retain source fallback, static replacement on/off, mixed text, vocal filtering and colors.','- Limits remain: 256 KiB lyric input, 128 KiB entry input, 96 KiB service reply, 600 lyric rows, 64 original rows/batch, 6800 URL characters and 2.5 seconds for translation; standard cache 128 entries/64000 characters, compact 64/32000; existing per-entry bounds remain.','- Ordinary first-load sampled heap changes are mostly small increases and some timings regress. Repairing formerly untranslated paths requires translation work. This release makes no universal speed/RAM reduction or VPN-stability claim.','','## Actual public translator requests','','The compiled Loon host mock sent self-written Korean/English sentences to the existing public translate.googleapis.com route. Both target languages returned 4/4 nonempty translations in 1 cold request; warm reopen was 0 requests. The route is separate from paid Google Cloud Translation and has no claimed official availability contract.']
for r in live['results']:out.append('- %s: cold elapsed %.3f seconds including the host mock; transport %.3f seconds; original rows preserved.'%(r['target'],r['milliseconds']/1000,r['transport'][0]['milliseconds']/1000))
out+=['','## Reproduction','','Install the exact dependencies from pnpm-lock.yaml. Build with node build.mjs, package with python3 package.py RUNTIME_COMMIT 1990, and run node --test --test-reporter=tap *.test.mjs core/test/*.test.mjs. Use reproduce-recovery.mjs BASELINE_317_SOURCE and run-measurements-318.py NODE BASELINE_317_SOURCE; the immutable baseline source/runtime is commit 898570540494794a4fc7efa0f97037b6049fd590. Hashes are frozen before/after every measurement step in bench-runtime-sha256.json. Full raw trials accompany these tables.','']
(p/'MEASUREMENTS.md').write_text('\n'.join(out))
report={'version':'3.1.8','baseline':'3.1.7','baselineSourceCommit':'898570540494794a4fc7efa0f97037b6049fd590','tests':1990,'addedTests':98,'newNativeClientFormatTests':60,'nodeFreshProcesses':408,'jscFreshProcesses':48,'mixedNativeResponses':4800,'warmHTTP':0,'peakMockHTTP':1,'arrivalPressureProcesses':16,'mockAdmissionTimers':0,'liveTranslatorRequests':2,'protectedSpotifyLyricResponseCaptured':False,'phoneUIAndVPNAcceptance':False,'runtimeHashes':'bench-runtime-sha256.json','fullMeasurements':'MEASUREMENTS.md'}
